{
  "rubric_title": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "applicability": "Applies to Software Engineers (all levels). Weightings and expectations should be calibrated to level and role scope.",
  "rating_scale": {
    "1": "Below Expectations",
    "2": "Partially Meets",
    "3": "Meets",
    "4": "Exceeds",
    "5": "Outstanding"
  },
  "weighting_guidelines": {
    "default": {
      "technical_excellence": 0.25,
      "execution_and_delivery": 0.20,
      "code_quality_and_maintainability": 0.15,
      "system_design_and_architecture": 0.10,
      "collaboration_and_communication": 0.10,
      "ownership_and_accountability": 0.08,
      "product_thinking_and_customer_impact": 0.07,
      "learning_and_growth": 0.05
    },
    "notes": "Adjust weights by role (e.g., senior/staff: increase system design; early-career: increase learning)."
  },
  "categories": [
    {
      "id": "technical_excellence",
      "name": "Technical Excellence",
      "description": "Depth and breadth of engineering skill; ability to solve complex problems and choose appropriate tools.",
      "behavioral_indicators": {
        "1": [
          "Struggles to implement tasks without significant guidance.",
          "Misapplies core concepts; frequent rework due to technical gaps."
        ],
        "2": [
          "Implements basic tasks with guidance; inconsistent understanding of core concepts.",
          "Occasional incorrect tool/tech selection leading to inefficiencies."
        ],
        "3": [
          "Independently implements most tasks; applies core concepts correctly.",
          "Selects appropriate tools/approaches for typical problems."
        ],
        "4": [
          "Handles complex, ambiguous problems; mentors others on technical topics.",
          "Improves frameworks/tooling for team-wide benefit."
        ],
        "5": [
          "Recognized expert; sets technical direction across teams/org.",
          "Introduces impactful innovations that measurably improve velocity, reliability, or cost."
        ]
      },
      "evidence_prompts": [
        "Examples of complex bugs/features solved and approach taken.",
        "Tooling/framework contributions and impact.",
        "Benchmarks or performance improvements with before/after metrics."
      ]
    },
    {
      "id": "execution_and_delivery",
      "name": "Execution and Delivery",
      "description": "Reliably delivers on commitments, manages scope, and drives tasks to completion.",
      "behavioral_indicators": {
        "1": [
          "Misses deadlines; requires frequent follow-ups.",
          "Poor task breakdown; blockers not escalated."
        ],
        "2": [
          "Occasionally slips on timelines; estimates are inconsistent.",
          "Escalates blockers but often late."
        ],
        "3": [
          "Meets agreed timelines; communicates risks early.",
          "Breaks work into actionable tasks; manages dependencies."
        ],
        "4": [
          "Consistently ahead of schedule; unblocks others.",
          "Improves team planning processes and estimation accuracy."
        ],
        "5": [
          "Drives large multi-team initiatives to timely completion.",
          "Establishes repeatable delivery practices that raise org reliability."
        ]
      },
      "evidence_prompts": [
        "Planned vs actual delivery dates; variance and causes.",
        "Project plans, dependency maps, risk mitigation examples."
      ]
    },
    {
      "id": "code_quality_and_maintainability",
      "name": "Code Quality and Maintainability",
      "description": "Produces clean, testable, maintainable code and improves codebase health.",
      "behavioral_indicators": {
        "1": [
          "Frequent defects; low test coverage; poor readability.",
          "Introduces tech debt without remediation plan."
        ],
        "2": [
          "Basic tests; style/architecture inconsistencies.",
          "Creates debt that is partially tracked but not resolved."
        ],
        "3": [
          "Clear, modular code; adequate tests; follows standards.",
          "Refactors opportunistically; documents key decisions."
        ],
        "4": [
          "Elevates code standards through reviews and tooling.",
          "Proactively pays down debt; improves test strategy and CI."
        ],
        "5": [
          "Leads codebase modernization; defines org-wide standards.",
          "Measurable reduction in defects and maintenance effort."
        ]
      },
      "evidence_prompts": [
        "Defect rates, test coverage trends, review feedback.",
        "Refactoring before/after, lint/tooling adoption impact."
      ]
    },
    {
      "id": "system_design_and_architecture",
      "name": "System Design and Architecture",
      "description": "Designs scalable, reliable, secure systems and makes sound tradeoffs.",
      "behavioral_indicators": {
        "1": [
          "Overlooks reliability/security/scalability requirements.",
          "Creates tightly coupled, brittle designs."
        ],
        "2": [
          "Designs for current needs but weak on future growth.",
          "Limited articulation of tradeoffs."
        ],
        "3": [
          "Produces solid designs with clear tradeoffs and documentation.",
          "Considers failure modes, cost, and observability."
        ],
        "4": [
          "Designs high-scale or mission-critical components; mentors peers.",
          "Runs effective design reviews; anticipates long-term evolution."
        ],
        "5": [
          "Defines architectural vision across teams; reduces systemic risk.",
          "Establishes patterns and reference architectures org-wide."
        ]
      },
      "evidence_prompts": [
        "Design docs, ADRs, review outcomes.",
        "SLA/SLOs, capacity planning, incident history and MTTR."
      ]
    },
    {
      "id": "collaboration_and_communication",
      "name": "Collaboration and Communication",
      "description": "Works well with others; communicates clearly with technical and non-technical stakeholders.",
      "behavioral_indicators": {
        "1": [
          "Poor responsiveness; unclear or incomplete updates.",
          "Conflicts escalate due to communication gaps."
        ],
        "2": [
          "Inconsistent updates; limited cross-functional collaboration.",
          "Feedback is vague or untimely."
        ],
        "3": [
          "Clear, timely communication; constructive in reviews.",
          "Effective collaboration with PM, Design, QA, and Ops."
        ],
        "4": [
          "Facilitates consensus; resolves conflicts productively.",
          "Improves team rituals; mentors on communication."
        ],
        "5": [
          "Trusted cross-org communicator; aligns diverse stakeholders.",
          "Sets communication standards and improves information flow."
        ]
      },
      "evidence_prompts": [
        "Stakeholder feedback, review comments, meeting notes.",
        "Examples of conflict resolution or alignment-building."
      ]
    },
    {
      "id": "ownership_and_accountability",
      "name": "Ownership and Accountability",
      "description": "Takes responsibility for outcomes; follows through and improves operational excellence.",
      "behavioral_indicators": {
        "1": [
          "Avoids accountability; leaves issues unresolved.",
          "Minimal involvement in on-call/operational duties."
        ],
        "2": [
          "Handles assigned tasks but limited follow-through on edge cases.",
          "Reactive to operational issues."
        ],
        "3": [
          "Owns features/services end-to-end; completes postmortems and action items.",
          "Participates in on-call responsibly; maintains runbooks."
        ],
        "4": [
          "Prevents recurrence through root cause fixes and automation.",
          "Improves on-call quality, SLOs, and operational processes."
        ],
        "5": [
          "Drives culture of ownership across teams; measurable reliability gains.",
          "Establishes operational excellence standards and tooling."
        ]
      },
      "evidence_prompts": [
        "Postmortems, incident metrics, SLO adherence.",
        "Runbooks, automation, reliability improvements."
      ]
    },
    {
      "id": "product_thinking_and_customer_impact",
      "name": "Product Thinking and Customer Impact",
      "description": "Understands user needs, aligns work to product goals, and measures impact.",
      "behavioral_indicators": {
        "1": [
          "Implements tickets without understanding user value.",
          "Builds features that miss key use cases."
        ],
        "2": [
          "Understands requirements but limited input on scope/ROI.",
          "Weak measurement of impact."
        ],
        "3": [
          "Validates requirements; considers usability and cost/benefit.",
          "Uses metrics to assess outcomes."
        ],
        "4": [
          "Shapes roadmap through data and user insights.",
          "Optimizes for impact and reduces waste."
        ],
        "5": [
          "Consistently delivers high-leverage outcomes; redefines problem spaces.",
          "Establishes product metrics frameworks used by multiple teams."
        ]
      },
      "evidence_prompts": [
        "Product metrics (adoption, retention, conversion).",
        "User research insights, A/B tests, hypothesis tracking."
      ]
    },
    {
      "id": "learning_and_growth",
      "name": "Learning and Growth",
      "description": "Continuously improves skills and helps others grow.",
      "behavioral_indicators": {
        "1": [
          "Resistant to feedback; limited growth.",
          "Does not share knowledge."
        ],
        "2": [
          "Accepts feedback but inconsistent application.",
          "Occasional knowledge sharing."
        ],
        "3": [
          "Actively seeks feedback; sets learning goals.",
          "Regularly shares knowledge via docs, talks, or pairing."
        ],
        "4": [
          "Mentors/coaches; elevates team capabilities.",
          "Drives adoption of best practices and learning programs."
        ],
        "5": [
          "Cultivates a learning culture across org; builds scalable mentorship systems.",
          "Recognized for thought leadership."
        ]
      },
      "evidence_prompts": [
        "Training completed, certifications, talks, mentorship outcomes.",
        "Documented feedback cycles and growth plans."
      ]
    }
  ],
  "leveling_guidance": {
    "associate_junior": "Focus on fundamentals, code quality, and reliable execution of scoped tasks.",
    "mid_level": "Independently deliver features end-to-end; contribute to design and team processes.",
    "senior": "Lead complex projects; elevate team standards; mentor peers; drive architectural improvements.",
    "staff_principal": "Set technical direction across teams; deliver cross-org impact; de-risk systems and influence strategy."
  },
  "calibration_notes": [
    "Use multiple evidence sources: code reviews, metrics, incident data, stakeholder feedback.",
    "Rate behaviors, not potential or popularity. Avoid recency and halo effects.",
    "Normalize expectations by role level and opportunity given.",
    "Document concrete examples for each rating."
  ],
  "overall_rating_computation": {
    "method": "Weighted average of category ratings using selected weights. Round to nearest 0.5.",
    "example": "overall = sum(category_rating * weight); ensure weights sum to 1.0"
  },
  "review_templates": {
    "employee_self_review": [
      "Top 3 accomplishments and their measurable impact.",
      "Challenges faced and how they were addressed.",
      "Examples aligned to each rubric category.",
      "Learning goals for next period and support needed."
    ],
    "manager_review": [
      "Summary of impact relative to role expectations.",
      "Evidence-backed ratings per category.",
      "Strengths and growth areas with actionable plans.",
      "Career development recommendations and next steps."
    ],
    "peer_feedback_prompts": [
      "What does this engineer do that helps the team most?",
      "Where could they improve to increase their impact?",
      "Examples of collaboration and communication effectiveness."
    ]
  },
  "periodic_goals_example": [
    {
      "goal": "Improve service reliability",
      "key_results": [
        "Reduce P1/P2 incidents by 30%",
        "Achieve 99.9% monthly SLO for core API",
        "Automate 3 recurring operational tasks"
      ],
      "linked_categories": ["execution_and_delivery", "ownership_and_accountability", "system_design_and_architecture"]
    },
    {
      "goal": "Elevate code quality",
      "key_results": [
        "Increase unit/integration test coverage from 55% to 75%",
        "Adopt static analysis and fix top 20 issues",
        "Publish coding standards doc and run 2 brown-bag sessions"
      ],
      "linked_categories": ["code_quality_and_maintainability", "learning_and_growth", "collaboration_and_communication"]
    }
  ],
  "privacy_and_fairness": [
    "Avoid sensitive personal attributes; focus strictly on job-related behaviors and outcomes.",
    "Ensure access to the same opportunities and calibrate across comparable roles.",
    "Give the employee a chance to respond and add context."
  ]
}

modified_pred:
{
  "title": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "timeframe": "H1 2025",
  "rating_scale": {
    "labels": [
      "1 - Does Not Meet Expectations",
      "2 - Partially Meets Expectations",
      "3 - Meets Expectations",
      "4 - Exceeds Expectations",
      "5 - Far Exceeds Expectations"
    ],
    "guidance": "Use whole numbers. A '3' indicates consistent, reliable performance at the expected level for the role. Calibrate across team."
  },
  "competencies": [
    {
      "name": "Technical Execution & Code Quality",
      "weight": 0.2,
      "description": "Ability to deliver correct, maintainable, and efficient code with appropriate tests and documentation.",
      "behavioral_indicators": {
        "1": [
          "Frequently introduces regressions or logic errors; requires constant oversight.",
          "Little to no test coverage; code lacks readability and standards compliance."
        ],
        "2": [
          "Delivers code with recurring quality issues; tests are inconsistent.",
          "Struggles with debugging and root cause analysis without guidance."
        ],
        "3": [
          "Delivers correct, readable, and maintainable code aligned with standards.",
          "Writes adequate unit/integration tests; effective debugging of own work."
        ],
        "4": [
          "Improves codebases through refactoring and patterns; reduces tech debt.",
          "Designs robust test suites; proactively prevents regressions."
        ],
        "5": [
          "Sets quality bar for the team; creates reusable libraries/patterns.",
          "Champions tooling and practices that materially elevate team-wide quality."
        ]
      },
      "evidence_examples": [
        "PRs merged without major rework; low defect escape rate.",
        "Meaningful unit/integration/E2E test coverage metrics.",
        "Refactor commits reducing complexity (e.g., cyclomatic complexity)."
      ]
    },
    {
      "name": "System Design & Architecture",
      "weight": 0.15,
      "description": "Designs components and systems that are scalable, reliable, secure, and cost-effective.",
      "behavioral_indicators": {
        "1": [
          "Proposes designs that do not meet basic functional or non-functional requirements."
        ],
        "2": [
          "Designs work for narrow cases but overlook scalability, reliability, or security tradeoffs."
        ],
        "3": [
          "Produces sound designs with clear APIs, data models, and tradeoff documentation."
        ],
        "4": [
          "Anticipates growth and failure modes; designs observability and resiliency in.",
