        ],
        "4": [
          "Facilitates productive discussions; mentors others in effective communication."
        ],
        "5": [
          "Trusted voice across teams; unblocks complex multi-party decisions."
        ]
      },
      "evidence_examples": [
        "Concise status updates; high-signal PR reviews; effective async communication.",
        "Well-run meetings; clear documentation."
      ]
    },
    {
      "name": "Problem Solving & Ownership",
      "weight": 0.15,
      "description": "Ability to diagnose issues, make decisions with incomplete information, and own outcomes end-to-end.",
      "behavioral_indicators": {
