original_pred:
{
  "rubric_name": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "scale": {
    "levels": [
      { "label": "1 - Needs Improvement", "description": "Frequently misses expectations; requires significant guidance." },
      { "label": "2 - Developing", "description": "Meets some expectations inconsistently; requires moderate guidance." },
      { "label": "3 - Meets Expectations", "description": "Consistently meets role expectations with normal guidance." },
      { "label": "4 - Exceeds Expectations", "description": "Often surpasses expectations; operates with high autonomy." },
      { "label": "5 - Outstanding", "description": "Consistently exemplary performance with organization-wide impact." }
    ],
    "guidance": "Select the level that best describes the engineer’s typical performance over the review period, not a single event."
  },
  "dimensions": [
    {
      "id": "technical_excellence",
      "name": "Technical Excellence",
      "weight": 0.2,
      "description": "Quality, maintainability, and correctness of code and technical designs.",
      "indicators": [
        "Produces clean, well-structured, testable, and secure code.",
        "Applies appropriate design patterns and architectural principles.",
        "Effectively debugs, profiles, and optimizes systems.",
        "Raises technical quality through reviews and standards."
      ],
      "behavioral_examples": {
        "1": ["Frequent defects in basic functionality; limited tests; code often rejected in review."],
        "3": ["Delivers maintainable code with adequate tests; resolves defects promptly; sound design choices."],
        "5": ["Introduces patterns and tooling that reduce defects org-wide; anticipates scalability and reliability needs."]
      }
    },
    {
      "id": "delivery_execution",
      "name": "Delivery and Execution",
      "weight": 0.18,
      "description": "Planning, estimating, prioritization, and reliable delivery of commitments.",
      "indicators": [
        "Breaks work into milestones with realistic estimates.",
        "Delivers on time or renegotiates proactively.",
        "Manages dependencies and reduces risk.",
        "Automates and improves developer workflows."
      ],
      "behavioral_examples": {
        "1": ["Misses deadlines without communication; poor estimation; blocks others."],
        "3": ["Meets most commitments; communicates risks; uses issue tracking effectively."],
        "5": ["Consistently delivers complex projects ahead of schedule; drives process improvements that raise team throughput."]
      }
    },
    {
      "id": "problem_solving",
      "name": "Problem Solving and Ownership",
      "weight": 0.14,
      "description": "Ability to decompose problems, make sound tradeoffs, and own outcomes end-to-end.",
      "indicators": [
        "Frames problems clearly with data and constraints.",
        "Selects pragmatic solutions balancing speed, quality, and cost.",
        "Owns incidents and follow-ups to resolution.",
        "Reflects and applies learnings to prevent recurrences."
      ],
      "behavioral_examples": {
        "1": ["Jumps to solutions without understanding requirements; frequent rework; drops follow-ups."],
        "3": ["Proposes reasonable options with tradeoffs; sees tasks through to completion."],
        "5": ["Shapes ambiguous problems into actionable plans; implements systemic fixes post-incident."]
      }
    },
    {
      "id": "system_design",
      "name": "System Design and Architecture",
      "weight": 0.12,
      "description": "Designs systems that are scalable, reliable, observable, and cost-effective.",
      "indicators": [
        "Creates clear design docs with alternatives and risks.",
        "Considers scalability, reliability, observability, privacy, and cost.",
        "Chooses appropriate data models and interfaces.",
        "Plans for migration, backward compatibility, and operability."
      ],
      "behavioral_examples": {
        "1": ["Designs lack clarity; ignores non-functional requirements; accrues unnecessary tech debt."],
        "3": ["Produces workable designs that meet current needs and anticipate near-term growth."],
        "5": ["Leads architecture that scales with business growth; mentors others in system design."]
      }
    },
    {
      "id": "collaboration",
      "name": "Collaboration and Communication",
      "weight": 0.12,
      "description": "Works effectively with cross-functional partners and communicates clearly.",
      "indicators": [
        "Communicates status, risks, and decisions with clarity and empathy.",
        "Participates constructively in code/design reviews.",
        "Collaborates with PM, Design, QA, and stakeholders.",
        "Adapts communication to audience; documents decisions."
      ],
      "behavioral_examples": {
        "1": ["Poor responsiveness; unclear updates; friction in reviews."],
        "3": ["Timely, clear communication; helpful feedback; reliable partner."],
        "5": ["Elevates team communication norms; resolves conflicts; aligns diverse stakeholders."]
      }
    },
    {
      "id": "impact_scope",
      "name": "Impact and Scope",
      "weight": 0.1,
      "description": "Magnitude and breadth of contributions across projects and teams.",
      "indicators": [
        "Delivers meaningful business/user outcomes.",
        "Takes on increasing scope and complexity.",
        "Unblocks others; amplifies team output.",
        "Influences priorities with data and customer insight."
      ],
      "behavioral_examples": {
        "1": ["Limited impact; requires close supervision; minimal ownership."],
        "3": ["Delivers impactful features; independently owns medium-scope projects."],
        "5": ["Leads multi-team initiatives; measurable business outcomes; sets technical direction."]
      }
    },
    {
      "id": "quality_security",
      "name": "Quality, Reliability, and Security",
      "weight": 0.06,
      "description": "Builds trustworthy systems and processes for quality and security.",
      "indicators": [
        "Writes and maintains tests; uses CI/CD and monitoring.",
        "Follows secure coding practices; addresses vulnerabilities.",
        "Participates in on-call with effective incident response.",
        "Defines SLOs and uses telemetry to maintain reliability."
      ],
      "behavioral_examples": {
        "1": ["Frequent regressions; overlooks security basics; poor incident hygiene."],
        "3": ["Stable releases with adequate test coverage; timely vulnerability remediation."],
        "5": ["Champions reliability and security culture; reduces incident rate and MTTR via systemic changes."]
      }
    },
    {
      "id": "mentorship_growth",
      "name": "Mentorship and Growth",
      "weight": 0.04,
      "description": "Supports others’ development and invests in own growth.",
      "indicators": [
        "Provides actionable feedback and guidance.",
        "Onboards and unblocks teammates.",
        "Creates learning resources and shares knowledge.",
        "Seeks feedback and grows skills aligned with role."
      ],
      "behavioral_examples": {
        "1": ["Limited knowledge sharing; resistant to feedback."],
        "3": ["Regularly helps peers and seeks feedback; documents learnings."],
        "5": ["Mentors across teams; establishes programs or resources that raise org capability."]
      }
    },
    {
      "id": "ownership_ethics",
      "name": "Ownership, Reliability, and Professionalism",
      "weight": 0.04,
      "description": "Dependability, accountability, and adherence to company values.",
      "indicators": [
        "Meets commitments and honors on-call responsibilities.",
        "Takes responsibility for outcomes and mistakes.",
        "Maintains respectful, inclusive behavior.",
        "Handles sensitive data and users ethically."
      ],
      "behavioral_examples": {
        "1": ["Unreliable follow-through; blames others; behavior issues."],
        "3": ["Dependable; owns mistakes and learns; models respectful conduct."],
        "5": ["Trusted owner for critical areas; upholds and improves team norms and ethics."]
      }
    }
  ],
  "rating_instructions": {
    "steps": [
      "Collect evidence: issues, PRs, design docs, incidents, metrics, peer feedback.",
      "Assess each dimension using indicators and examples; pick a level 1-5.",
      "Provide concise, evidence-based comments for each rating.",
      "Weight ratings by dimension to compute overall score.",
      "Calibrate across peers to ensure fairness and consistency.",
      "Set 2-3 SMART goals for the next review period."
    ],
    "evidence_guidance": [
      "Prefer verifiable, recent examples over opinions.",
      "Account for scope and context (e.g., on-call load, project complexity).",
      "Evaluate typical behavior over time, not isolated incidents."
    ]
  },
  "scoring": {
    "method": "Weighted average of dimension ratings (1-5) using provided weights.",
    "example": {
      "weights_sum": 1.0,
      "formula": "overall = sum(weight_i * rating_i)",
      "interpretation": [
        { "range": "4.5 - 5.0", "label": "Outstanding" },
        { "range": "3.8 - 4.49", "label": "Exceeds Expectations" },
        { "range": "3.0 - 3.79", "label": "Meets Expectations" },
        { "range": "2.0 - 2.99", "label": "Developing" },
        { "range": "< 2.0", "label": "Needs Improvement" }
      ]
    }
  },
  "reviewer_comments_template": {
    "summary": "",
    "strengths": [],
    "areas_for_growth": [],
    "notable_achievements": [],
    "collaboration_feedback": "",
    "quality_security_feedback": "",
    "system_design_feedback": "",
    "goals_next_period": [
      {
        "goal": "",
        "metric_of_success": "",
        "deadline": "",
        "dependencies_or_support": ""
      }
    ],
    "additional_notes": ""
  },
  "employee_self_review_template": {
    "top_achievements": [],
    "what_i_learned": [],
    "challenges_and_mitigations": [],
    "impact_metrics": [],
    "feedback_requests": [],
    "career_development_interests": []
  },
  "calibration_guidance": {
    "principles": [
      "Rate based on impact and scope relative to level expectations.",
      "Normalize ratings across teams and projects.",
      "Avoid bias from recency, halo/horns, or similarity effects."
    ],
    "checks": [
      "Are ratings supported by multiple concrete examples?",
      "Is scope considered (complexity, ambiguity, cross-team coordination)?",
      "Are demographics or personal style influencing ratings inappropriately?"
    ]
  },
  "leveling_note": "Interpret this rubric relative to the engineer’s job level. For example, a 'Meets Expectations' at Senior implies higher scope and autonomy than at Mid-level.",
  "privacy_note": "Do not include sensitive personal data. Store reviews according to company policy."
}

