{
  "rubric_name": "Software Engineer Performance Review Rubric",
  "version": "1.0",
  "rating_scale": {
    "1": "Unsatisfactory",
    "2": "Needs Improvement",
    "3": "Meets Expectations",
    "4": "Exceeds Expectations",
    "5": "Outstanding"
  },
  "guidance": {
    "how_to_use": [
      "Rate each criterion using the 1–5 scale.",
      "Provide evidence and examples for each rating.",
      "Weight criteria as defined; adjust weights if role-specific priorities differ.",
      "Identify strengths, growth areas, and concrete next steps."
    ],
    "role_levels": [
      "Use the same rubric across levels; calibrate expectations for scope, autonomy, and impact.",
      "For senior roles, emphasize systems thinking, cross-team impact, and mentoring."
    ],
    "evidence_sources": [
      "Code reviews, design docs, incident reports, on-call history",
      "Peer feedback, product metrics, delivery timelines",
      "OKRs, sprint reports, customer support issues"
    ]
  },
  "criteria": [
    {
      "id": "technical_excellence",
      "name": "Technical Excellence",
      "weight": 0.20,
      "description": "Quality, reliability, and maintainability of code; sound technical decisions; appropriate use of patterns and tools.",
      "behaviors": {
        "1": [
          "Introduces frequent defects; code often unreviewable or non-functional.",
          "Requires heavy guidance for basic tasks; misuses core tools/technologies."
        ],
        "2": [
          "Inconsistent code quality; gaps in testing and documentation.",
          "Struggles with non-trivial problems; technical debt accumulation."
        ],
        "3": [
          "Writes readable, maintainable, and tested code.",
          "Makes sound technical choices for scope; addresses known issues promptly."
        ],
        "4": [
          "Improves existing systems’ reliability/performance.",
          "Elevates codebase standards; proactively reduces technical debt."
        ],
        "5": [
          "Recognized as a go-to expert; sets technical direction.",
          "Delivers significant architectural improvements with measurable impact."
        ]
      },
      "evidence_prompts": [
        "Examples of PRs demonstrating quality and test coverage.",
        "Defect rates, rollback incidents, or post-release quality metrics.",
        "Design decisions and trade-offs documented."
      ]
    },
    {
      "id": "delivery_execution",
      "name": "Delivery and Execution",
      "weight": 0.18,
      "description": "Ability to plan, estimate, prioritize, and deliver work predictably.",
      "behaviors": {
        "1": [
          "Misses commitments frequently; blockers not communicated.",
          "Requires continuous supervision to progress."
        ],
        "2": [
          "Estimates are often inaccurate; scope creep unmanaged.",
          "Deadlines occasionally missed; limited risk mitigation."
        ],
        "3": [
          "Meets commitments; communicates risks early.",
          "Breaks work into milestones; manages dependencies."
        ],
        "4": [
          "Consistently delivers ahead of schedule; de-risks complex work.",
          "Improves team planning and estimation practices."
        ],
        "5": [
          "Leads complex, multi-team deliveries with high predictability.",
          "Establishes repeatable execution frameworks that raise team throughput."
        ]
      },
      "evidence_prompts": [
        "Sprint/iteration outcomes vs. commitments.",
        "Throughput/cycle time trends.",
        "Examples of risk identification and mitigation."
      ]
    },
    {
      "id": "system_design",
      "name": "System Design and Architecture",
      "weight": 0.14,
      "description": "Designs scalable, secure, cost-effective systems; makes trade-offs explicit.",
      "behaviors": {
        "1": [
          "Designs are brittle; ignores constraints like scalability and security."
        ],
        "2": [
          "Designs work for small scope but lack future-proofing; limited trade-off analysis."
        ],
        "3": [
          "Produces clear designs with justified choices and alignment to requirements."
        ],
        "4": [
          "Anticipates growth, operates within cost/SLA targets; reduces complexity."
        ],
        "5": [
          "Architects systems that become standards; mentors others in design thinking."
        ]
      },
      "evidence_prompts": [
        "Design docs, ADRs, and review feedback.",
        "Load, latency, availability, and cost metrics post-implementation."
      ]
    },
    {
      "id": "code_quality_practices",
      "name": "Code Quality and Practices",
      "weight": 0.10,
      "description": "Adherence to standards, testing, documentation, CI/CD, and review practices.",
      "behaviors": {
        "1": [
          "Lacks tests and documentation; frequent build breakages."
        ],
        "2": [
          "Basic tests present but shallow; inconsistent documentation."
        ],
        "3": [
          "Maintains solid test coverage; follows CI/CD and style guides."
        ],
        "4": [
          "Improves pipelines; adds linters, tooling, and documentation patterns."
